// Wind and rain moving the plants in the startup wallpaper (bamboo, the big tree, grass, flowers, bushes).
// WebGL redraws fengyu-rural-storm.png with a small displacement read from SWAY_MAP: red = how far the spot sways
// (roots 0, tips most), green = leaf flutter and raindrop hits, blue = stiffness (grass quick, tree slow).
// Gusts travel from left to right like the painted rain. Anything that fails leaves the still picture in place.
const SWAY_MAP = 'data:image/png;base64,';

const VERTEX = `
attribute vec2 aPos;
varying vec2 vUv;
void main() { vUv = vec2(aPos.x * 0.5 + 0.5, 0.5 - aPos.y * 0.5); gl_Position = vec4(aPos, 0.0, 1.0); }`;

const FRAGMENT = `
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
uniform sampler2D uImg;
uniform sampler2D uMap;
uniform vec2 uSize;
uniform float uTime;
uniform float uGain;
varying vec2 vUv;
float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
void main() {
  vec2 px = vUv * uSize;
  vec3 m = texture2D(uMap, vUv).rgb;
  float amp = m.r * uGain;
  float leaf = m.g * uGain;
  float t = uTime;
  // gusts: a slow pattern drifting to the right across the picture
  float u = px.x / uSize.x;
  float g = u * 0.55 - t * 0.11;
  float gust = 0.5 + 0.5 * (0.55 * sin(g * 3.1416) + 0.3 * sin(g * 5.84 + 1.7) + 0.15 * sin(g * 13.2 + 0.4));
  gust = smoothstep(0.12, 0.92, gust);
  // each plant swings at its own pace; neighbours stay nearly in step so stems bend instead of wobbling
  float w = 2.0 + 3.6 * m.b;
  float ph = 1.3 * sin(px.x * 0.0061 + px.y * 0.0037) + 0.8 * sin(px.y * 0.0105 - px.x * 0.0042);
  float sway = 0.72 * sin(t * w - u * 2.6 + ph) + 0.28 * sin(t * w * 2.13 + ph * 1.7 + 0.6);
  float dx = (0.62 * (gust - 0.34) + 0.38 * sway * (0.3 + 0.7 * gust)) * amp * 18.0;
  vec2 d = vec2(dx, abs(dx) * 0.2);
  // leaves trembling
  vec2 q = px / 5.0;
  d += vec2(sin(q.x * 1.3 + t * 9.0 + sin(q.y * 1.7 + t * 6.1)), sin(q.y * 1.1 - t * 8.3 + sin(q.x * 1.9 - t * 5.2)))
    * leaf * (0.4 + 0.6 * gust) * 0.6;
  // raindrops knocking single leaves down for a moment
  vec2 cell = floor(px / 14.0);
  vec2 f = fract(px / 14.0);
  float period = 0.7 + 2.0 * hash(cell);
  float tt = t + hash(cell + 17.0) * period;
  float k = floor(tt / period);
  float tau = tt - k * period;
  float on = step(hash(cell + k * 1.37 + 3.0), 0.42);
  float bump = sin(3.1416 * f.x) * sin(3.1416 * f.y);
  d.y += on * exp(-tau * 7.5) * sin(tau * 30.0) * bump * bump * leaf * 2.2;
  // never drag a still thing (fence, post, wall) into a moving spot: fade the move where it would pull from one
  float there = texture2D(uMap, vUv - d / uSize).r;
  d *= clamp((there + 0.01) / (m.r + 0.01), 0.0, 1.0);
  gl_FragColor = vec4(texture2D(uImg, vUv - d / uSize).rgb, 1.0);
}`;

function loadImage(src) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error('sway map did not load'));
    img.src = src;
  });
}

function whenLoaded(img) {
  if (img.complete && img.naturalWidth) return Promise.resolve(img);
  return new Promise((resolve, reject) => {
    img.addEventListener('load', () => resolve(img), { once: true });
    img.addEventListener('error', () => reject(new Error('wallpaper did not load')), { once: true });
  });
}

// The wallpaper comes from a file:// address; if WebGL refuses it as foreign data, read the bytes through the game.
function readThroughGame(readFile, path) {
  return new Promise((resolve, reject) => {
    if (typeof readFile !== 'function' || typeof createImageBitmap !== 'function') { reject(new Error('no readFile')); return; }
    readFile(path, data => {
      createImageBitmap(new Blob([data], { type: 'image/png' })).then(resolve, reject);
    }, reject);
  });
}

export function startFengyuSway({ layer, poster, readFile, path, size }) {
  const [W, H] = size;
  const canvas = document.createElement('canvas');
  canvas.className = 'xd-fy-sway';
  const options = { alpha: false, antialias: false, depth: false, stencil: false, preserveDrawingBuffer: false, powerPreference: 'low-power' };
  const gl = canvas.getContext('webgl', options) || canvas.getContext('experimental-webgl', options);
  if (!gl) return null;

  function shader(type, source) {
    const s = gl.createShader(type);
    gl.shaderSource(s, source); gl.compileShader(s);
    if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(s) || 'shader');
    return s;
  }
  const program = gl.createProgram();
  gl.attachShader(program, shader(gl.VERTEX_SHADER, VERTEX));
  gl.attachShader(program, shader(gl.FRAGMENT_SHADER, FRAGMENT));
  gl.linkProgram(program);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program) || 'link');
  gl.useProgram(program);
  const quad = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, quad);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
  const aPos = gl.getAttribLocation(program, 'aPos');
  gl.enableVertexAttribArray(aPos);
  gl.vertexAttribPointer(aPos, 2, gl.FLOAT, false, 0, 0);
  const uTime = gl.getUniformLocation(program, 'uTime');
  const uGain = gl.getUniformLocation(program, 'uGain');
  gl.uniform2f(gl.getUniformLocation(program, 'uSize'), W, H);
  gl.uniform1i(gl.getUniformLocation(program, 'uImg'), 0);
  gl.uniform1i(gl.getUniformLocation(program, 'uMap'), 1);

  function texture(unit, source, raw) {
    gl.activeTexture(gl.TEXTURE0 + unit);
    const tex = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, tex);
    gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
    gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
    gl.pixelStorei(gl.UNPACK_COLORSPACE_CONVERSION_WEBGL, raw ? gl.NONE : gl.BROWSER_DEFAULT_WEBGL);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGB, gl.RGB, gl.UNSIGNED_BYTE, source);
    return tex;
  }

  // start in a lull so the first gust builds up after the scene appears
  let stopped = false, frame = 0, last = 0, time = 4, shown = 0, counted = 0, slow = 0;
  function render() {
    const ease = Math.min(1, shown / 3);
    gl.uniform1f(uTime, time);
    gl.uniform1f(uGain, ease * ease * (3 - 2 * ease));
    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
  }
  function fit() {
    const w = layer.clientWidth || innerWidth, h = layer.clientHeight || innerHeight;
    const contain = getComputedStyle(poster).objectFit === 'contain';
    const scale = (contain ? Math.min : Math.max)(w / W, h / H);
    Object.assign(canvas.style, {
      left: `${(w - W * scale) / 2}px`, top: `${(h - H * scale) / 2}px`, width: `${W * scale}px`, height: `${H * scale}px`,
    });
    // never more pixels than the picture has: the picture is upscaled on big screens anyway
    const density = Math.max(0.5, Math.min(1, (globalThis.devicePixelRatio || 1) * scale));
    canvas.width = Math.round(W * density); canvas.height = Math.round(H * density);
    gl.viewport(0, 0, canvas.width, canvas.height);
    render(); // a resized canvas is blank until drawn again
  }
  function draw(now) {
    if (stopped) return;
    frame = requestAnimationFrame(draw);
    const raw = last ? Math.max(0, (now - last) / 1000) : 0; last = now;
    const dt = Math.min(0.1, raw);
    time = (time + dt) % 3600; shown += dt;
    // a computer that cannot keep up (e.g. no graphics card acceleration) gets the still picture back
    if (shown > 2 && raw > 0) {
      counted++; if (raw > 0.05) slow++;
      if (counted >= 120) { if (slow > 60) { api.stop(); return; } counted = slow = 0; }
    }
    render();
  }
  function lost(event) { event.preventDefault(); api.stop(); }
  canvas.addEventListener('webglcontextlost', lost);

  const api = {
    stop() {
      if (stopped) return; stopped = true;
      cancelAnimationFrame(frame);
      removeEventListener('resize', fit);
      canvas.removeEventListener('webglcontextlost', lost);
      canvas.remove();
      gl.getExtension('WEBGL_lose_context')?.loseContext();
    },
  };

  const picture = whenLoaded(poster).then(img => {
    if (stopped) return null;
    try { return texture(0, img, false); }
    catch (error) {
      if (error?.name !== 'SecurityError') throw error;
      return readThroughGame(readFile, path).then(bitmap => stopped ? null : texture(0, bitmap, false));
    }
  });
  Promise.all([picture, loadImage(SWAY_MAP)]).then(([tex, map]) => {
    if (stopped || !tex) return;
    texture(1, map, true);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, tex);
    fit(); addEventListener('resize', fit); // first frame is drawn before the canvas shows: no black flash
    poster.after(canvas);
    frame = requestAnimationFrame(draw);
  }).catch(error => { console.warn('风雨植物摆动未加载', error); api.stop(); });
  return api;
}
